// settings.ts
// Centralized CMS settings: upload limits + personal info.
//
// Future-proof design: the public surface (UPLOAD_LIMITS, useCmsSettings) is
// stable. When the DB-backed version lands later, swap the internals of
// useCmsSettings() and the constants can be moved to the same remote source
// without any consumer of this module needing to change.

import { useCallback, useEffect, useState } from "react";
import { AUTH_ID } from "./keys";

const SETTINGS_KEY = `${AUTH_ID}_settings`;

// v1 hardcoded limits. Move to the same remote store as personal info when DB lands.
export const UPLOAD_LIMITS = {
  maxTotalImages: 100,
  maxConcurrentUploads: 3,
} as const;

export type PersonalField = { value: string; isPublic: boolean };

export type CmsSettings = {
  personalInfo: {
    name: PersonalField;
    businessName: PersonalField;
    phone: PersonalField;
    email: PersonalField;
  };
};

export type PersonalInfoKey = keyof CmsSettings["personalInfo"];

const DEFAULT_SETTINGS: CmsSettings = {
  personalInfo: {
    name:         { value: "", isPublic: false },
    businessName: { value: "", isPublic: false },
    phone:        { value: "", isPublic: false },
    email:        { value: "", isPublic: false },
  },
};

// Deep-merge persisted settings over defaults so adding new fields later
// doesn't require a migration.
const read = (): CmsSettings => {
  if (typeof localStorage === "undefined") return DEFAULT_SETTINGS;
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (!raw) return DEFAULT_SETTINGS;
    const parsed = JSON.parse(raw);
    return {
      ...DEFAULT_SETTINGS,
      ...parsed,
      personalInfo: {
        ...DEFAULT_SETTINGS.personalInfo,
        ...(parsed.personalInfo ?? {}),
      },
    };
  } catch {
    return DEFAULT_SETTINGS;
  }
};

const write = (data: CmsSettings): void => {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(SETTINGS_KEY, JSON.stringify(data));
};

export const useCmsSettings = () => {
  const [settings, setSettings] = useState<CmsSettings>(DEFAULT_SETTINGS);

  // Hydrate from storage on mount (avoids SSR mismatch).
  useEffect(() => { setSettings(read()); }, []);

  const updatePersonal = useCallback(
    (key: PersonalInfoKey, patch: Partial<PersonalField>) => {
      setSettings(prev => {
        const next: CmsSettings = {
          ...prev,
          personalInfo: {
            ...prev.personalInfo,
            [key]: { ...prev.personalInfo[key], ...patch },
          },
        };
        write(next);
        return next;
      });
    },
    []
  );

  return { settings, updatePersonal };
};
