// useImageSyncQueue.ts

import { IMAGE_SYNC_QUEUE } from "./keys";

const STORAGE_KEY = IMAGE_SYNC_QUEUE
const STALE_THRESHOLD_MS = 10 * 60 * 1000;
// Upload-specific cutoff: auto-clear stuck uploads after 5 minutes (MTC-BRI-19).
// Applied in getUploads() so every reader implicitly cleans up.
const UPLOAD_STALE_MS = 5 * 60 * 1000;

// ── Types ─────────────────────────────────────────
type QueueItem = {
  time: number;
  action: "delete" | "upload";
  // Upload-only fields (used by the perception-engineering notification layer)
  fileName?: string;
  webpUrl?: string;
  step?: number;
  // 200x200 cover JPEG as a data URL — survives reload (unlike blob: URLs).
  // Removed automatically when markSuccess() clears the entry (MTC-BRI-05).
  thumb?: string;
};

type Queue = Record<string, QueueItem>;

export type SyncQueueState = {
  id: string;
  action: string;
  ageMs: number;
  status: "uploading" | "success" | "stale";
};

// Shape consumed by <UploadNotifications/>. Only includes upload entries
// that have a webpUrl (the thing we poll on).
export type UploadEntry = {
  id: string;
  time: number;
  fileName: string;
  webpUrl: string;
  step: number;
  thumb?: string;
};

export type SyncQueueOptions = {
  addToErrorLog?: (error: any) => void;
};

// ── Storage ───────────────────────────────────────
const readQueue = (): Queue => {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}");
  } catch {
    return {};
  }
};

const writeQueue = (data: Queue): void => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

// ── Hook ──────────────────────────────────────────
export const useImageSyncQueue = (options: SyncQueueOptions = {}) => {
  const { addToErrorLog = console.error } = options;

  // ── Upload tracking ─────────────────────────────
  // Call this right after a successful upload POST (when we have the webpUrl).
  // The notification layer reads these entries, shows mock progress steps,
  // and polls the webpUrl until it's reachable.
  const queueUpload = (
    id: string,
    meta?: { fileName?: string; webpUrl?: string; thumb?: string }
  ): void => {
    const data = readQueue();
    data[id] = {
      time: Date.now(),
      action: "upload",
      step: 0,
      ...meta,
    };
    writeQueue(data);
  };

  // Called by the notification layer each poll tick so the step survives reload.
  const updateStep = (id: string, step: number): void => {
    const data = readQueue();
    if (data[id]) {
      data[id] = { ...data[id], step };
      writeQueue(data);
    }
  };

  // Called by the notification layer when HEAD on webpUrl succeeds.
  const markSuccess = (id: string): void => {
    const data = readQueue();
    delete data[id];
    writeQueue(data);
  };

  // Returns only upload entries that have a webpUrl (pollable).
  // As a side effect, auto-drops any upload older than UPLOAD_STALE_MS
  // so the "one upload at a time" lock can never get permanently stuck (MTC-BRI-19).
  const getUploads = (): UploadEntry[] => {
    const data = readQueue();
    const now = Date.now();
    const cleaned: Queue = {};
    let changed = false;

    for (const [id, item] of Object.entries(data)) {
      if (item.action === "upload" && now - item.time > UPLOAD_STALE_MS) {
        addToErrorLog({ id, ...item, ageMs: now - item.time, reason: "upload_stale_5min" });
        changed = true;
        continue; // drop
      }
      cleaned[id] = item;
    }

    if (changed) writeQueue(cleaned);

    return Object.entries(cleaned)
      .filter(([, item]) => item.action === "upload" && !!item.webpUrl)
      .map(([id, item]) => ({
        id,
        time: item.time,
        fileName: item.fileName ?? "image",
        webpUrl: item.webpUrl!,
        step: item.step ?? 0,
        thumb: item.thumb,
      }));
  };

  // Is there a non-stale upload currently in progress? (MTC-BRI-17)
  // Uses the same 5-minute cutoff as getUploads so a stuck upload can't
  // permanently block the UI.
  const isUploading = (): boolean => {
    const data = readQueue();
    const now = Date.now();
    return Object.values(data).some(
      (item) => item.action === "upload" && now - item.time <= UPLOAD_STALE_MS
    );
  };

  // ── Delete tracking ─────────────────────────────
  const queueDelete = (id: string): void => {
    const data = readQueue();
    data[id] = { time: Date.now(), action: "delete" };
    writeQueue(data);
  };

  const clearEntry = (id: string): void => {
    const data = readQueue();
    delete data[id];
    writeQueue(data);
  };

  // ── Reconcile (runs on each files.json load) ────
  // Rules:
  //   • delete entry — drop once it's no longer present in rows (succeeded)
  //   • upload entry — NEVER auto-succeed from rows (tempIds don't appear
  //     in files.json). Success is determined solely by webpUrl polling
  //     in <UploadNotifications/>, which calls markSuccess().
  //   • Either — drop if older than STALE_THRESHOLD_MS (backend missed it).
  const reconcile = <T extends { id: string }>(
    rows: T[]
  ): { filteredRows: T[]; states: SyncQueueState[] } => {
    const queue = readQueue();
    const rowIds = new Set(rows.map((r) => r.id));
    const now = Date.now();
    const updatedQueue: Queue = {};
    const states: SyncQueueState[] = [];

    for (const [id, item] of Object.entries(queue)) {
      const ageMs = now - item.time;
      let status: SyncQueueState["status"] = "uploading";

      if (ageMs > STALE_THRESHOLD_MS) {
        status = "stale";
        addToErrorLog({ id, ...item, ageMs });
        states.push({ id, action: item.action, ageMs, status });
        continue; // drop from queue
      }

      if (item.action === "delete") {
        if (rowIds.has(id)) {
          // still in files.json → pending delete, keep
          updatedQueue[id] = item;
        }
        // else: gone from files.json → deleted successfully, drop
      } else if (item.action === "upload") {
        // uploads are cleared only by webpUrl polling (markSuccess)
        updatedQueue[id] = item;
      }

      states.push({ id, action: item.action, ageMs, status });
    }

    writeQueue(updatedQueue);

    // Only delete-action entries hide rows from the UI.
    const filteredRows = rows.filter((row) => {
      const q = updatedQueue[row.id];
      return !q || q.action !== "delete";
    });

    return { filteredRows, states };
  };

  const debug = (): void => {
    console.log("[ImageSyncQueue RAW]", readQueue());
  };

  return {
    // upload
    queueUpload,
    updateStep,
    markSuccess,
    getUploads,
    isUploading,
    // delete
    queueDelete,
    clearEntry,
    // shared
    reconcile,
    check: reconcile,
    debug,
  };
};
